B=Path(__file__).resolve().parent
f=E.Element('mxfile',host='Electron');d=E.SubElement(f,'diagram',id='module5-training',name='Module 5 - Model Training')
g=E.SubElement(d,'mxGraphModel',grid='1',gridSize='10',page='1',pageScale='1',pageWidth='3400',pageHeight='2360',background='#FFFFFF');r=E.SubElement(g,'root')
E.SubElement(r,'mxCell',id='0');E.SubElement(r,'mxCell',id='1',parent='0')
